-- PRODUCTION CLEAN-UP — generated by scripts/make-production-cleanup.mjs, do not edit by hand.
-- Removes (1) the demo data (all rows tagged DMO…) and (2) what the automated tests left behind (test dockets
-- "T" + up to 7 letters/digits, rows marked TST / ZTA / 777 / 999 / G-99000… / TS99…). Real entries are not touched.
-- One transaction: either everything is removed or nothing. Safe to run again.
set nocount on;
set xact_abort on;
begin transaction;

-- the test dockets (narrow: T + 1..7 letters / digits; real docket numbers never look like this)
if object_id('tempdb..#td') is not null drop table #td;
create table #td (d varchar(50) primary key);
insert into #td(d) select docket_no from grn_master
 where docket_no like 'T%' and len(docket_no) between 2 and 8 and docket_no not like '%[^A-Za-z0-9]%';
declare @testDockets int = (select count(*) from #td);
declare @demoDockets int = (select count(*) from grn_master where docket_no like 'DMO%');
print concat('Demo dockets: ', @demoDockets, ', test dockets: ', @testDockets);

-- (1) demo data
delete from tblAccountTrasaction where VoucherNo like 'DMO%';
delete from Franchisee_Invoice_Detail where F_Invoice_No like 'DMOFINV%';
delete from Franchisee_Invoice where F_Invoice_No like 'DMOFINV%';
delete from Vendor_Invoice_Verify_Details where Vendor_Bill_No like 'DMOVB%';
delete from Vendor_Invoice_Verify where Vendor_Bill_No like 'DMOVB%';
delete from OtherVendorInvoice where InvoiceNo like 'DMOOTH%';
delete from miscellaneous_bill where Bill_No like 'DMOMIS%';
delete from warehouse_bill where Bill_No like 'DMOWHO%';
delete from Bill_Receive_Details where BR_No like 'DMOBR%';
delete from Bill_Receive where BR_No like 'DMOBR%';
delete from client_bill_charge_details where bill_no like 'DMOBL%';
delete from client_bill where bill_no like 'DMOBL%';
delete from pod_received where IOM_number like 'DMOIOM%';
delete from pod_dispatch where IOM_number like 'DMOIOM%';
delete from delivery_status_entry_grn where docket_no like 'DMO%';
delete from delivery_status_entry_details where docket_no like 'DMO%';
delete from drs_entry_details_grn where Drs_no like 'DMODRS%';
delete from drs_entry_details where Drs_no like 'DMODRS%';
delete from Arrival_Packg where ArrivalNo like 'DMOAR%';
delete from Arrival_entry where ArrivalNo like 'DMOAR%';
delete from dispatch_master where challan_no like 'DMOCH%';
delete from Manifest_grn where Manifest_no like 'DMOMF%';
delete from mainfest_entry where mainfest_no like 'DMOMF%';
delete from Pick_Up_grn where Pickup_no like 'DMOPK%';
delete from Pick_up_entry where pickup_no like 'DMOPK%';
delete from docket_tracking where docket_no like 'DMO%';
delete from docket_other_charges where docket like 'DMO%';
delete from grn_docket_charge where Docket_No like 'DMO%';
delete from grn_master where docket_no like 'DMO%';
delete from client_Master where client_code like 'DMOC%';

-- (2) automated-test leftovers (same order as the tests' own clean-up)
delete from tblManifestBag where ManifestNo in (select ManifestNo from tblManifestBagDocket where DocketNo in (select d from #td));
delete from tblManifestBagDocket where DocketNo in (select d from #td);
delete from docket_international where docket_no in (select d from #td);
delete from New_Location_master where Location_Code in ('TL99', 'TL98');
delete from Driver_master where Drivername like 'TST DRIVER%';
delete from tblAccountLedger where VendorOrClientCode = 'VT9901';
delete from temp_vendors_master where vendor_code = 'VT9901';
delete from grn_docket_charge where Docket_No in (select d from #td);
delete from docket_other_charges where docket in (select d from #td);
delete from docket_invoice where docketNo in (select d from #td);
delete from docket_insurance where docketNo in (select d from #td);
delete from docket_dimension where docket_no in (select d from #td);
delete from docket_charge_entry where Docket_No in (select d from #td);
delete from docket_franchisee_comm where Docket_No in (select d from #td);
delete from docket_tracking where docket_no in (select d from #td);
delete from delivery_status_entry_details where docket_no in (select d from #td);
delete from delivery_status_entry_grn where docket_no in (select d from #td);
delete from octroi_bill_charge_details where docket_no in (select d from #td);
delete from octroi_bill where remarks like 'TST%' or bill_no not in (select bill_no from octroi_bill_charge_details);
delete from tblAccountTrasaction where Mode in ('Miscellaneous Bill Finalized', 'Warehouse Bill Finalized') and VoucherNo in (select Bill_No from miscellaneous_bill where remarks like 'TST%' union select Bill_No from warehouse_bill where remarks like 'TST%');
delete from miscellaneous_bill where remarks like 'TST%';
delete from warehouse_bill where remarks like 'TST%';
delete from tblAccountTrasaction where Mode = 'PURCHASE/PAYBILL' and VoucherNo in (select InvoiceNo from OtherVendorInvoice where Narration like 'TST%');
delete from OtherVendorInvoice_Details where InvoiceNo in (select InvoiceNo from OtherVendorInvoice where Narration like 'TST%');
delete from OtherVendorInvoiceCostProfit where InvoiceNo in (select InvoiceNo from OtherVendorInvoice where Narration like 'TST%');
delete from OtherVendorInvoice where Narration like 'TST%';
delete from Vendor_Invoice_Verify_Details where challan_no like 'TVC%';
delete from Vendor_Invoice_Verify where Narration like 'TST%' or Vendor_Bill_No not in (select Vendor_Bill_No from Vendor_Invoice_Verify_Details);
delete from Dispatch_Master where challan_no like 'TVC%';
delete from Franchisee_Invoice_Detail where Docket_No in (select d from #td) or F_Invoice_No in (select F_Invoice_No from Franchisee_Invoice where Remarks like 'TST%');
delete from Franchisee_Invoice where Remarks like 'TST%';
delete from tblAccountTrasaction where Mode = 'BILL RECEIVE' and VoucherNo in (select BR_No from Bill_Receive_Details where Bill_no in (select bill_no from client_bill_charge_details where docket_no in (select d from #td)));
delete from Bill_Receive where BR_No in (select BR_No from Bill_Receive_Details where Bill_no in (select bill_no from client_bill_charge_details where docket_no in (select d from #td)));
delete from Bill_Receive_Details where Bill_no in (select bill_no from client_bill_charge_details where docket_no in (select d from #td));
delete from tblAccountTrasaction where Mode = 'Bill Finalized' and VoucherNo in (select bill_no from client_bill_charge_details where docket_no in (select d from #td));
delete from client_bill where bill_no in (select bill_no from client_bill_charge_details where docket_no in (select d from #td));
delete from client_bill_cancel where docket_no in (select d from #td);
delete from client_bill_charge_details where docket_no in (select d from #td);
delete from pod_dispatch_image where docket_no in (select d from #td);
delete from pod_dispatch where docket_no in (select d from #td);
delete from pod_received where docket_no in (select d from #td);
delete from POD_Dispatch_D where Doc_No in (select d from #td) or IOM_No not in (select IOM_number from pod_dispatch where IOM_number is not null);
delete from POD_Dispatch_H where Doc_No not in (select Doc_No from POD_Dispatch_D);
delete from drs_entry_details_grn where docket_no in (select d from #td);
delete from drs_entry_details where Drs_no not in (select Drs_no from drs_entry_details_grn);
delete from Arrival_Packg where docket_no in (select d from #td);
delete from Arrival_entry where ArrivalNo not in (select ArrivalNo from Arrival_Packg);
delete t from tblAccountTrasaction t join dispatch_master d on d.challan_no = t.VoucherNo
 where t.Mode = 'CHALLAN' and exists (select 1 from Manifest_grn g where g.docket_no in (select d from #td)
                                     and ',' + d.manifest_no + ',' like '%,' + g.Manifest_no + ',%');
delete d from dispatch_master d where exists (select 1 from Manifest_grn g where g.docket_no in (select d from #td)
                                             and ',' + d.manifest_no + ',' like '%,' + g.Manifest_no + ',%');
delete from Arrival_entry where challan_no not in (select challan_no from dispatch_master);
delete from Loading_Sheet where Ls_no in (select Ls_no from Loading_Sheet_Details where docket_no in (select d from #td));
delete from Loading_Sheet_Details where docket_no in (select d from #td);
delete from Manifest_grn where docket_no in (select d from #td);
delete from mainfest_entry where mainfest_no not in (select Manifest_no from Manifest_grn);
delete from Pick_Up_grn where docket_no in (select d from #td);
delete from Pick_up_entry where pickup_no not in (select Pickup_no from Pick_Up_grn);
delete from grn_master where docket_no in (select d from #td);
delete from tblAccountLedger where LedgerName like '%TST %';
delete from branch_master where branch_name like 'TST %';
delete from Vechile_Master where VEHICLE_NO like 'TST%' or VEHICLE_NO like 'TS99%';
delete from tblAccountLedger where LedgerName like 'TS99%';
update tblAccountLedger set IsActive = 1 where LedgerName = 'TDS PAYABLE';  -- in case a run stopped inside the challan test
delete from vendors_master where Name like 'TST %';
-- test Paid / To Pay general rates carry notification_days '999'
delete from ClientRate_With_Slab where EntRef in (select EntRef from client_contract_city where isnull(client_code, '') = '' and notification_days = '999');
delete from client_contract_city where isnull(client_code, '') = '' and notification_days = '999';
delete from client_contract_location where isnull(client_code, '') = '' and notification_days = '999';
delete from client_contract_State where isnull(client_code, '') = '' and notification_days = '999';
delete from client_contract_zone where isnull(client_code, '') = '' and notification_days = '999';
delete from ODA_Charge where Distance = 777;                     -- test ODA rates
delete from PRS_DRS_RATE_MASTER where Fix_Km_Rate = 777 or Per_Kg = 777;   -- test PRS / DRS rates
-- settings: test rows carry TST remarks / headers, tst…@example.com, ODA bands from 90000, series G-99000…, trucks TS99…
delete from Bind_Franchisee_To_Client where ClientID in (select client_code from client_Master where company_name like 'TST %');
delete from Client_email where email like 'tst%@example.com';
delete from Auto_MIS_Header_footer where Header like 'TST %';
delete from ODA_Configuration_Master where ODA_Distance_ID in (select ID from ODA_Distance_Master where from_distance >= 90000)
                                      or ODA_Weight_ID in (select ID from ODA_Weight_Master where from_weight >= 90000);
delete from ODA_Distance_Master where from_distance >= 90000;
delete from ODA_Weight_Master where from_weight >= 90000;
delete from Shipper_issue_frombranch_tobranch where shipper_no like 'G-99000%';
delete from shiper_issue_to_branch where starting_series like 'G-99000%';
delete from shipper_master where starting_series like 'G-99000%';
delete from GatePasshipper_master where starting_series like 'G-99000%';
delete from grn_master_splapl where docket_no in (select d from #td);
delete from Freight_THC_Margin_Approval_Details where remarks like 'TST%';
delete from vendor_vehicle_master where truck_no like 'TS99%' or vehicle_no like 'TS99%';
delete from vendor_road_rate_master where ftl_amount = 777 or ftl_pkg = 777 or ftl_pkm = 777;
delete from Vendor_Air_Slab_Rate where Air_Rate_Code in (select Air_Rate_Code from Vendor_Air_RateMaster where Rate_pkg = 777);
delete from Vendor_Air_RateMaster where Rate_pkg = 777;
delete from Vendor_Train_Rate where TripCost = 777 or rate = 777;
delete from Franchisee_Commission_Master_Detail where CommId in (select Comm_Code from Franchisee_Commission_Master where Rent = 777);
delete from Franchisee_Commission_Master where Rent = 777;
delete from FranchiseeCommissionMaster where Pickup = 777;
delete from General_Rate_With_Slab where EntRef in (
  select EntRef from GenaraleRate_Master_City where notification_days = '999' union select EntRef from General_Rate_location where notification_days = '999'
  union select EntRef from General_Rate_State where notification_days = '999' union select EntRef from General_Rate_zone where notification_days = '999');
delete from GenaraleRate_Master_City where notification_days = '999';
delete from General_Rate_location where notification_days = '999';
delete from General_Rate_State where notification_days = '999';
delete from General_Rate_zone where notification_days = '999';
delete from ClientRate_With_Slab where client_id in (select client_code from client_Master where company_name like 'TST %');
delete from ClientRate_Category_Slab where client_id in (select client_code from client_Master where company_name like 'TST %');
delete from Min_chargeRate_slab where client_code in (select client_code from client_Master where company_name like 'TST %');
delete from client_contract_city where client_code in (select client_code from client_Master where company_name like 'TST %');
delete from client_contract_location where client_code in (select client_code from client_Master where company_name like 'TST %');
delete from client_contract_State where client_code in (select client_code from client_Master where company_name like 'TST %');
delete from client_contract_zone where client_code in (select client_code from client_Master where company_name like 'TST %');
delete from client_Master where company_name like 'TST %';
delete from users where user_id in (select empcode from employee_master where empname like 'TST %');
delete from employee_master where empname like 'TST %';

-- accounts tests (ZTA …)
delete from tblAccountTrasaction where Mode = 'Payment Note' and VoucherNo in (select Payment_No from tbl_payment where Narration like 'ZTA%');
delete from tbl_payment_detail where Payment_No in (select Payment_No from tbl_payment where Narration like 'ZTA%');
delete from tbl_payment where Narration like 'ZTA%';
delete from tblAccountTrasaction where Mode = 'Contra Note' and VoucherNo in (select Contra_No from tbl_contra where Narration like 'ZTA%');
delete from tbl_contra where Narration like 'ZTA%';
delete from tblAccountTrasaction where VoucherNo like 'ZTA%' or LedgerCode in (select LedgerCode from tblAccountLedger where LedgerName like 'ZTA %');
delete from tblLedgerHierarchy where LedgerCode in (select LedgerCode from tblAccountLedger where LedgerName like 'ZTA %');
delete from tblAccountLedger where LedgerName like 'ZTA %';
delete from tblAccountGroupInfo where GroupCode in (select GroupCode from tblAccountGroup where GroupName like 'ZTA %');
delete from tblAccountGroup where GroupName like 'ZTA %';

-- pickups / manifests left empty after the dockets went
delete from Pick_up_entry where pickup_no not in (select Pickup_no from Pick_Up_grn);
delete from mainfest_entry where mainfest_no not in (select Manifest_no from Manifest_grn);

drop table #td;
commit;
print 'Production clean-up done';
